package com.ke.ticketsystemke.service;
import com.ke.ticketsystemke.dto.*;import com.ke.ticketsystemke.entity.*;import com.ke.ticketsystemke.repository.WarrantyReminderRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.util.*;import java.util.function.Predicate;
@Service public class WarrantyReminderService{private static final ZoneId ZONE=ZoneId.of("Asia/Kolkata");private static final Set<String>SORTS=Set.of("PRIORITY","DUE_DATE","NEWEST","OLDEST");private final WarrantyReminderRepository repo;private final AccessService access;@Value("${warranty.reminders.max-snooze-days:${WARRANTY_REMINDER_MAX_SNOOZE_DAYS:30}}")int maxSnoozeDays;public WarrantyReminderService(WarrantyReminderRepository r,AccessService a){repo=r;access=a;}
 @Transactional(readOnly=true)public WarrantyReminderPageResponse list(WarrantyReminderFilter f,String actor){authorize(actor);validate(f);boolean manager=access.isAllowed(actor,AccessKey.MANAGE_WARRANTY_REMINDERS);List<WarrantyReminder> rows=repo.findAllDetailed().stream().filter(visible(actor,manager)).filter(filters(f,actor,manager)).sorted(sort(f.getSort())).toList();int from=Math.min(rows.size(),f.getPage()*f.getSize()),to=Math.min(rows.size(),from+f.getSize());return new WarrantyReminderPageResponse(rows.subList(from,to).stream().map(this::map).toList(),f.getPage(),f.getSize(),rows.size(),(rows.size()+f.getSize()-1)/f.getSize(),manager);}
 @Transactional(readOnly=true)public WarrantyReminderDailySummary summary(String actor){authorize(actor);boolean manager=access.isAllowed(actor,AccessKey.MANAGE_WARRANTY_REMINDERS);LocalDate today=LocalDate.now(ZONE);List<WarrantyReminder> a=repo.findAllDetailed().stream().filter(visible(actor,manager)).filter(r->r.getStatus()!=WarrantyReminderStatus.RESOLVED&&r.getStatus()!=WarrantyReminderStatus.SUPERSEDED).toList();return new WarrantyReminderDailySummary(today,count(a,r->r.getStatus()==WarrantyReminderStatus.OPEN),count(a,WarrantyReminder::isOverdue),count(a,r->r.getPriority()==WarrantyReminderPriority.CRITICAL),count(a,r->r.getRecipientEmployeeId()==null),count(a,r->Set.of(WarrantyReminderType.FOLLOW_UP_DUE,WarrantyReminderType.COMPLAINT_FOLLOW_UP_DUE).contains(r.getReminderType())&&today.equals(r.getDueDate())),count(a,r->r.getReminderType()==WarrantyReminderType.EXPECTED_VISIT_OVERDUE),count(a,r->r.getReminderType()==WarrantyReminderType.EXPECTED_REPLACEMENT_OVERDUE),count(a,r->Set.of(WarrantyReminderType.READY_TO_DELIVER,WarrantyReminderType.REPLACEMENT_READY_FOR_DELIVERY).contains(r.getReminderType())),count(a,r->r.getReminderType()==WarrantyReminderType.AWAITING_CUSTOMER_DECISION),count(a,r->r.getReminderType()==WarrantyReminderType.REQUIRED_DOCUMENTS_MISSING),a.stream().max(Comparator.comparingInt(WarrantyReminder::getDaysOverdue)).map(r->r.getWarrantyClaim().getId()).orElse(null),count(a,r->today.equals(r.getDueDate())),manager);}
 @Transactional public WarrantyReminderResponse acknowledge(Long id,WarrantyReminderAcknowledgeRequest req,String actor){WarrantyReminder r=mutable(id,req.version(),actor);if(r.getStatus()==WarrantyReminderStatus.RESOLVED||r.getStatus()==WarrantyReminderStatus.SUPERSEDED)conflict("Reminder is no longer active");r.setStatus(WarrantyReminderStatus.ACKNOWLEDGED);r.setAcknowledgedAt(Instant.now());r.setAcknowledgedByEmployeeId(actor);r.setAcknowledgementNote(trim(req.note(),1000));return map(repo.save(r));}
 @Transactional public WarrantyReminderResponse snooze(Long id,WarrantyReminderSnoozeRequest req,String actor){WarrantyReminder r=mutable(id,req.version(),actor);if(r.getStatus()==WarrantyReminderStatus.RESOLVED||r.getStatus()==WarrantyReminderStatus.SUPERSEDED)conflict("Reminder is no longer active");Instant now=Instant.now(),max=now.plus(maxSnoozeDays,java.time.temporal.ChronoUnit.DAYS);if(!req.snoozedUntil().isAfter(now)||req.snoozedUntil().isAfter(max))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Snooze must be in the future and within "+maxSnoozeDays+" days");r.setStatus(WarrantyReminderStatus.SNOOZED);r.setSnoozedUntil(req.snoozedUntil());r.setSnoozedByEmployeeId(actor);r.setSnoozeReason(req.reason().trim());return map(repo.save(r));}
 private WarrantyReminder mutable(Long id,Long version,String actor){authorize(actor);WarrantyReminder r=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Reminder not found"));boolean manager=access.isAllowed(actor,AccessKey.MANAGE_WARRANTY_REMINDERS);if(!visible(actor,manager).test(r))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Access denied");if(!Objects.equals(version,r.getVersion()))conflict("Reminder was updated by another user");return r;}
 private Predicate<WarrantyReminder> visible(String actor,boolean manager){return r->manager||r.getRecipientEmployeeId()!=null&&r.getRecipientEmployeeId().equalsIgnoreCase(actor);}
 private Predicate<WarrantyReminder> filters(WarrantyReminderFilter f,String actor,boolean manager){return r->{WarrantyReminderStatus wanted=f.getStatus();if(wanted==null&&r.getStatus()!=WarrantyReminderStatus.OPEN)return false;if(wanted!=null&&r.getStatus()!=wanted)return false;if(f.getPriority()!=null&&r.getPriority()!=f.getPriority())return false;if(f.getReminderType()!=null&&r.getReminderType()!=f.getReminderType())return false;if(Boolean.TRUE.equals(f.getAssignedToMe())&&!(r.getRecipientEmployeeId()!=null&&r.getRecipientEmployeeId().equalsIgnoreCase(actor)))return false;if(!manager&&r.getRecipientEmployeeId()==null)return false;if(Boolean.TRUE.equals(f.getUnassigned())&&r.getRecipientEmployeeId()!=null)return false;if(Boolean.TRUE.equals(f.getEscalated())&&!r.isEscalated())return false;if(Boolean.TRUE.equals(f.getOverdue())&&!r.isOverdue())return false;if(f.getClaimId()!=null&&!f.getClaimId().equals(r.getWarrantyClaim().getId()))return false;if(f.getTicketId()!=null&&!f.getTicketId().equals(r.getTicket().getId()))return false;if(f.getDueFrom()!=null&&(r.getDueDate()==null||r.getDueDate().isBefore(f.getDueFrom())))return false;return f.getDueTo()==null||r.getDueDate()!=null&&!r.getDueDate().isAfter(f.getDueTo());};}
 private Comparator<WarrantyReminder> sort(String s){Comparator<WarrantyReminder> c=switch(s){case"DUE_DATE"->Comparator.comparing(WarrantyReminder::getDueDate,Comparator.nullsLast(Comparator.naturalOrder()));case"NEWEST"->Comparator.comparing(WarrantyReminder::getCreatedAt).reversed();case"OLDEST"->Comparator.comparing(WarrantyReminder::getCreatedAt);default->Comparator.comparingInt((WarrantyReminder r)->priority(r.getPriority())).thenComparing(Comparator.comparingInt(WarrantyReminder::getDaysOverdue).reversed());};return c.thenComparing(WarrantyReminder::getId);}
 private int priority(WarrantyReminderPriority p){return switch(p){case CRITICAL->0;case HIGH->1;case NORMAL->2;case LOW->3;};}private void validate(WarrantyReminderFilter f){if(f.getPage()<0||f.getSize()<1||f.getSize()>100)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Page must be non-negative and size between 1 and 100");if(!SORTS.contains(f.getSort()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported reminder sort");if(f.getDueFrom()!=null&&f.getDueTo()!=null&&f.getDueFrom().isAfter(f.getDueTo()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid due-date range");}private void authorize(String actor){access.requireAllowed(actor,AccessKey.VIEW_TICKETS);access.requireAllowed(actor,AccessKey.VIEW_WARRANTY_REMINDERS);}private long count(List<WarrantyReminder>a,Predicate<WarrantyReminder>p){return a.stream().filter(p).count();}private String trim(String s,int max){if(s==null||s.isBlank())return null;String v=s.trim();return v.length()>max?v.substring(0,max):v;}private void conflict(String m){throw new ResponseStatusException(HttpStatus.CONFLICT,m);}
 private WarrantyReminderResponse map(WarrantyReminder r){Ticket t=r.getTicket();WarrantyClaim c=r.getWarrantyClaim();return new WarrantyReminderResponse(r.getId(),t.getId(),t.getTicketNumber(),c.getId(),t.getCustomerName(),t.getProductType(),c.getManufacturerName(),r.getReminderType(),r.getTitle(),r.getMessage(),r.getStatus(),r.getPriority(),r.getRecipientEmployeeId(),r.getRecipientEmployeeNameSnapshot(),r.getDueDate(),r.isOverdue(),r.getDaysOverdue(),r.isEscalated(),r.getEscalationLevel(),r.getPendingActionCode(),r.getCreatedAt(),r.getAcknowledgedAt(),r.getSnoozedUntil(),r.getResolvedAt(),r.getVersion());}
}
